::-webkit-scrollbar-track {
  background: var(--scrollbar-bg-normal-color) !important; /* track color */
}

::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar-handle-bg-normal-color) !important;
  border: 0;
  border-radius: 5px;
}

::-webkit-scrollbar-thumb:hover {
  background-color: var(--scrollbar-border-normal-color) !important; /* darker on hover */
}

.schedule-dialog .schedule-type-selection {
  margin-bottom: 35px;
}

.schedule-dialog .schedule-type-header {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 12px;
}

.schedule-dialog .schedule-type-cards {
  display: flex;
  gap: 35px;
  width: 1075px;
}

.schedule-dialog .schedule-type-card {
  flex: 1;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1.5px solid #e5e7eb;
  background: #ffffff;
  cursor: pointer;
  text-align: left;
  transition: all 0.2s ease-in-out;
}

.schedule-dialog .schedule-type-card:hover {
  border-color: #c7d2fe;
}

.schedule-dialog .schedule-type-card.selected {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.schedule-dialog .radio-indicator {
  margin-top: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2px solid #9ca3af;
  position: relative;
  flex-shrink: 0;
}

.schedule-type-card.selected .radio-indicator {
  border-color: #2563eb;
}

.schedule-dialog .schedule-type-card.selected .radio-indicator::after {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  background: #2563eb;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.schedule-dialog .schedule-type-card-title {
  display: block;
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
  color: #111827;
}

.schedule-dialog .schedule-type-card-description {
  display: block;
  font-size: 13px;
  line-height: 1.4;
  color: #6b7280;
}

.d-none {
  display: none !important;
}

.data-driven-datasource-popup {
  background: #ffffff;
}
.data-driven-datasource-popup #data-driven-dataset-info {
  border-color: rgb(59, 130, 246);
  margin-bottom: 25px;
}
.data-driven-datasource-popup #data-driven-dataset-info .su-info {
  margin-top: 3px;
  color: rgb(59, 130, 246);
}
.data-driven-datasource-popup #data-driven-dataset-info .data-driven-dataset-info-description {
  color: #1f2937;
}
.data-driven-datasource-popup .data-driven-section-header {
  margin-bottom: 24px;
}
.data-driven-datasource-popup .data-driven-section-header .data-driven-section-title {
  font-size: 16px;
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 4px;
}
.data-driven-datasource-popup .data-driven-section-header .data-driven-section-subtitle {
  font-size: 13px;
  color: #6b7280;
}
.data-driven-datasource-popup .datasource-field label {
  display: block;
  font-size: 13px;
  font-weight: 500;
  color: #1f2937;
  margin-bottom: 6px;
}
.data-driven-datasource-popup .datasource-field label .mandatory {
  color: #dc2626;
  margin-left: 2px;
}
.data-driven-datasource-popup .datasource-field .validation-message {
  font-size: 12px;
  color: #dc2626;
  margin-top: 4px;
  min-height: 16px;
}
.data-driven-datasource-popup .datasource-field #configured-dataset-dropdown_hidden, .data-driven-datasource-popup .datasource-field #configured-datasource-dropdown_hidden {
  padding: 8px;
}

.bootstrap-select {
  width: 100% !important;
}
.bootstrap-select .dropdown-toggle {
  height: 40px;
  padding: 8px 12px;
  font-size: 13px;
  color: #1f2937;
  background-color: #ffffff;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  box-shadow: none;
  display: flex;
  align-items: center;
}
.bootstrap-select .dropdown-toggle:hover {
  border-color: #9ca3af;
}
.bootstrap-select .dropdown-toggle:focus, .bootstrap-select .dropdown-toggle:active {
  outline: none;
  border-color: #2563eb;
  box-shadow: 0 0 0 1px #2563eb;
}
.bootstrap-select .dropdown-toggle .filter-option {
  white-space: nowrap;
}
.bootstrap-select .dropdown-menu {
  border-radius: 6px;
  border: 1px solid #d1d5db;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
}
.bootstrap-select .dropdown-menu li a {
  padding: 8px 12px;
  font-size: 13px;
  color: #1f2937;
}
.bootstrap-select .dropdown-menu li a:hover {
  background-color: #f3f4f6;
}
.bootstrap-select .dropdown-menu li.selected a {
  background-color: #eff6ff;
  color: #2563eb;
}

.source-select {
  height: 38px;
  padding-right: 2rem;
}

.value-field input,
.value-field select {
  height: 40px;
  padding: 8px 12px;
  font-size: 13px;
  border-radius: 6px;
  border: 1px solid #d1d5db;
}
.value-field input:focus,
.value-field select:focus {
  border-color: #2563eb;
  box-shadow: 0 0 0 1px #2563eb;
  outline: none;
}
.value-field .error-message {
  font-size: 12px;
  color: #dc2626;
  margin-top: 4px;
  min-height: 16px;
}

.dataset-field .field-error-text {
  font-size: 12px;
  color: #dc2626;
  margin-top: 4px;
  line-height: 1.4;
  min-height: 16px;
}
.dataset-field.has-error .bootstrap-select .dropdown-toggle {
  border-color: #dc2626 !important;
  box-shadow: none !important;
}

.storage-option.d-none {
  display: none;
}

.d-none {
  display: none !important;
}

.data-driven-datasource-popup,
.delivery-options-wrapper {
  background: #ffffff;
}
.data-driven-datasource-popup h3,
.data-driven-datasource-popup .data-driven-section-title,
.delivery-options-wrapper h3,
.delivery-options-wrapper .data-driven-section-title {
  font-size: 16px;
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 6px;
}
.data-driven-datasource-popup .desc,
.data-driven-datasource-popup .data-driven-section-subtitle,
.delivery-options-wrapper .desc,
.delivery-options-wrapper .data-driven-section-subtitle {
  font-size: 13px;
  color: #6b7280;
  margin-bottom: 24px;
}

.delivery-options-wrapper {
  padding: 24px 32px;
}

.delivery-row {
  display: flex;
  align-items: flex-start;
}
.delivery-row label {
  width: 200px;
  padding-top: 10px;
  font-size: 14px;
  font-weight: 500;
  color: #1f2937;
}
.delivery-row .field-group {
  display: flex;
  gap: 16px;
  flex: 1;
}

.form-select {
  height: 40px;
  padding: 8px 36px 8px 12px;
  font-size: 12px;
  color: #1f2937;
  border-radius: 6px;
  background-color: #ffffff;
  border: 1px solid #d1d5db;
  box-shadow: none;
  cursor: pointer;
}
.form-select:hover {
  border-color: #9ca3af;
}
.form-select:focus {
  border-color: #2563eb;
  outline: none;
  box-shadow: 0 0 0 1px #2563eb;
}
.form-select:disabled {
  background-color: #f9fafb;
  color: #6b7280;
  cursor: not-allowed;
}

.form-select option {
  font-size: 13px;
  color: #1f2937;
}

.form-select option:checked {
  background-color: #eff6ff;
  color: #2563eb;
}

.form-select option:hover {
  background-color: #f3f4f6;
}

.value-input {
  height: 40px;
  padding: 8px 12px;
  font-size: 13px;
  border-radius: 6px;
  border: 1px solid #d1d5db;
}
.value-input:focus {
  border-color: #2563eb;
  outline: none;
  box-shadow: 0 0 0 1px #2563eb;
}

.field-error-text,
.validation-message {
  font-size: 12px;
  color: #dc2626;
  margin-top: 4px;
  min-height: 16px;
  line-height: 1.4;
}

.has-error .form-select,
.has-error .value-input {
  border-color: #dc2626 !important;
  box-shadow: none !important;
}

.datasource-field label {
  font-size: 18px;
  font-weight: bold;
}

.schedule-dialog .delivery-grid {
  display: flex;
  flex-direction: column;
}

.delivery-settings-shell {
  padding: 28px 32px 20px;
  background: #fff;
}
.delivery-settings-shell .delivery-settings-header {
  margin-bottom: 8px;
}
.delivery-settings-shell .delivery-settings-title {
  margin: 0 0 6px;
  font-size: 20px;
  font-weight: 700;
  color: #111827;
}
.delivery-settings-shell .delivery-settings-subtitle {
  margin: 0;
  font-size: 14px;
  color: #667085;
}
.delivery-settings-shell .delivery-settings-layout {
  display: flex;
  grid-template-columns: 240px minmax(0, 1fr) 360px;
  gap: 5px;
  align-items: start;
}
.delivery-settings-shell .delivery-method-panel,
.delivery-settings-shell .delivery-config-card {
  border-radius: 5px;
  background: #fff;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.04);
}
.delivery-settings-shell .delivery-method-panel {
  padding: 22px 20px;
  width: 230px;
  height: 385px;
}
.delivery-settings-shell .delivery-method-title,
.delivery-settings-shell .delivery-card-title {
  font-size: 16px;
  font-weight: 700;
  color: #111827;
  padding-bottom: 5px;
  border-bottom: 1px solid gray;
  margin-bottom: 17px;
}
.delivery-settings-shell .delivery-method-option {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  margin-bottom: 20px;
  cursor: pointer;
